CREATE TABLE orders(id UUID PRIMARY KEY,user_id UUID NOT NULL,status VARCHAR(30) NOT NULL,total NUMERIC(12,2) NOT NULL,created_at TIMESTAMPTZ NOT NULL,updated_at TIMESTAMPTZ NOT NULL);CREATE TABLE order_items(id UUID PRIMARY KEY,order_id UUID NOT NULL REFERENCES orders(id) ON DELETE CASCADE,product_id UUID NOT NULL,quantity INT NOT NULL,unit_price NUMERIC(12,2) NOT NULL);CREATE INDEX idx_orders_user_created ON orders(user_id,created_at DESC);CREATE TABLE processed_events(event_id UUID PRIMARY KEY,processed_at TIMESTAMPTZ NOT NULL DEFAULT now());
